      "tipo": "DrawCalls",
      "causa_raiz": "Volume extremo de Draw Calls atingindo o pico de 13.967 chamadas por quadro (o orcamento maximo e de 2.579), provocando sobrecarga severa na GPU (41.78ms vs 16.67ms maximo). O problema e causado por renderizacao fragmentada de objetos individuais sem agrupamento (batching), proliferacao de materiais e instanciacao individual de meshes repetidos em vez de GPU Instancing.",
      "codigo_refatorado": "using UnityEngine;

public class BatchedRenderer : MonoBehaviour
{
    [Header("Configuracoes de Instanciacao")]
    [SerializeField] private Mesh targetMesh;
    [SerializeField] private Material instancedMaterial;
    [SerializeField] private Transform[] instancesTransforms;

    private Matrix4x4[] matrices;
    private MaterialPropertyBlock propertyBlock;
    private const int MaxBatchSize = 1023;

    private void Awake()
    {
        if (instancedMaterial != null)
        {
            instancedMaterial.enableInstancing = true;
        }

        propertyBlock = new MaterialPropertyBlock();
        InitializeMatrices();
    }

    private void InitializeMatrices()
    {
        if (instancesTransforms == null || instancesTransforms.Length == 0)
            return;

        matrices = new Matrix4x4[instancesTransforms.Length];
        for (int i = 0; i < instancesTransforms.Length; i++)
        {
            if (instancesTransforms[i] != null)
            {
                matrices[i] = instancesTransforms[i].localToWorldMatrix;
            }
        }
    }

    private void Update()
    {
        if (targetMesh == null || instancedMaterial == null || matrices == null || matrices.Length == 0)
            return;

        int totalInstances = matrices.Length;
        for (int i = 0; i < totalInstances; i += MaxBatchSize)
        {
            int currentBatchCount = Mathf.Min(MaxBatchSize, totalInstances - i);
            Graphics.DrawMeshInstanced(
                targetMesh,
                0,
                instancedMaterial,
                matrices,
                currentBatchCount,
                propertyBlock,
                UnityEngine.Rendering.ShadowCastingMode.On,
                true
            );
        }
    }
}",
      "explicacao_didatica": "Imagine o processador (CPU) como um chefe de cozinha e a placa de video (GPU) como o cozinheiro. Toda vez que a CPU manda desenhar um unico tijolo ou arvore, ela emite uma ordem chamada 'Draw Call'. Ao fazer quase 14 mil chamadas por quadro, o cozinheiro fica soterrado de papeis e o jogo engasga a 41ms. Usando GPU Instancing e agrupamento de malhas, transformamos 1000 ordens individuais em um unico pedido: 'desenhe estes 1000 tijolos de uma so vez'. Isso reduz drasticamente o trabalho de comunicacao e devolve a taxa para 60 FPS estaveis."
    }
  ],
  "dicas_level_design": "1. Habilitar 'Static' em todos os elementos de cenario imoveis (paredes, rochas, pisos) e ativar Static Batching nas configuracoes de Player. 2. Gerar Texture Atlases para combinar multiplas texturas em uma unica, reduzindo a quantidade de materiais distintos no cenario. 3. Habilitar a opcao 'Enable GPU Instancing' em todos os materiais de objetos repetitivos (vegetacao, detritos, postes, caixas). 4. Configurar Occlusion Culling (Window > Rendering > Occlusion Culling) e fazer o bake da cena para nao renderizar salas e props ocultos atras de paredes. 5. Configurar grupos de LOD (Level of Detail) com culling de distancia para descartar objetos pequenos antes que sobrecarreguem a contagem de submissao."
}

